Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='filepermaintype', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='One file holds one main type, and the type comes first', body='Name a file for the concept of its main type, and put that type first after the imports. A file that grows a second main type is split in two. A grab-bag file named utils, helpers, common or misc is split by type.', rationale='A reader learns the model from folder names and from the first lines of each file.', supersedes=()))